def ols(y, X, cl=None, names=None):
    X = np.asarray(X, float); y = np.asarray(y, float)
    XtX = X.T@X; iX = np.linalg.pinv(XtX); b = iX@(X.T@y); e = y - X@b
    if cl is None:
        V = iX * (e@e)/(len(y)-X.shape[1])
    else:
